export type GeckoTerminalTokenMapping = {
  tokenId: string;
  canonicalChainId: string;
  gtNetworkId: string | null;
  tokenAddress: string | null;
  identityNote: string;
  mappingEvidence?: string;
  unmappedReason?: string;
};
/**
 * GeckoTerminal identity is network + exact contract/coin-type address, the same
 * identity policy already applied for DEX Screener. Each mapped row reuses the
 * DEX Screener-verified exact address (see dexscreener-token-mappings.ts) and
 * translates the chain to GeckoTerminal own network id, confirmed against the
 * standalone GeckoTerminal Public API GET /networks catalog (which also
 * publishes each network CoinGecko asset-platform id for cross-checking),
 * originally checked 2026-09-26. A wrapped representation is never substituted
 * for a native asset, matching the DEX Screener mapping policy.
 *
 * Reconciled 2026-09-28 against the current 238-token canonical universe (see
 * src/data/canonical-tokens.ts). Every canonical token has an explicit row:
 * either an exact GeckoTerminal mapping or a documented unmappedReason. Of the
 * 238 canonical tokens, 63 are mapped and 175 are explicitly
 * unmapped. The 100 tokens covered by the original integration (63 mapped, 37
 * unmapped) are unchanged. None of the 138 tokens added to the canonical
 * universe since then have a DEX Screener-verified exact address to reuse
 * (dexscreener-token-mappings.ts has not been extended to them either), so
 * every one of them is left explicitly unmapped rather than guessed from a
 * ticker, name, or another chain deployment.
 */
